def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return clamp_step(b - a)

    def dist1(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def safe_pos(value, default):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def best_by_distance(items, origin, reverse=False):
        best_item = None
        best_score = None
        for item in items:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            score = dist1((item[0], item[1]), origin)
            if best_item is None:
                best_item = item
                best_score = score
            else:
                if reverse:
                    if score > best_score:
                        best_item = item
                        best_score = score
                else:
                    if score < best_score:
                        best_item = item
                        best_score = score
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position"), (0, 0))
    ox, oy = safe_pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [step_toward(sx, ox), step_toward(sy, oy)]
        candidates = [
            (0, 0),
            (0, max(0, h - 1)),
            (max(0, w - 1), 0),
            (max(0, w - 1), max(0, h - 1)),
        ]
        target = best_by_distance(candidates, (ox, oy), reverse=True)
        if target is None:
            return [0, 0]
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = best_by_distance(targets, (sx, sy), reverse=False)
        if target is None:
            # Expand toward opponent if nothing obvious.
            return [step_toward(sx, ox), step_toward(sy, oy)]
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by_distance(resources, (sx, sy), reverse=False)
    if target is None:
        # If no resources visible, move toward opponent or stay put.
        return [step_toward(sx, ox), step_toward(sy, oy)]
    return [step_toward(sx, target[0]), step_toward(sy, target[1])]

